(()=>{$(document).ready(function(){$("#right-side").append('<a href="#" id="conclude-all-btn" class="btn button-sidebar-wide"><i class="icon-user"></i> Conclude All Students</a>'),$("#conclude-all-btn").on("click",function(n){n.preventDefault(),u()})});async function u(){let n=$(".user_list").find("li").toArray(),t=n.length;c(0,t);for(let l=0;l<t;l++){var a=CURRENT_COURSE_ID,e=$(n[l]).attr("id");e&&(enrollmentId=e.replace("enrollment_",""),await o(a,enrollmentId)),c(l+1,t)}$("#conclude-all-btn").html('<i class="icon-user"></i> Conclude All Students')}async function o(n,t){await $.ajax({url:`/api/v1/courses/${n}/enrollments/${t}`,type:"DELETE",data:{task:"conclude"}})}function c(n,t){$("#conclude-all-btn").html(`Concluding ${n} / ${t} Students`)}})();
